local bundle={["placeId"]=93959280828322,["beforeCapture"]="scripts/lighting_realism/backup/after.json @ 2026-10-06 15:01:04",["operations"]={{["kind"]="source",["path"]={"ReplicatedStorage","Modules","Game","World","LightingClient"},["class_name"]="ModuleScript",["before"]="-- Sole environment property writer in Continuous mode. Context decisions stay with their owners.\nlocal Client={}\nlocal started=false\nlocal continuous=false\nlocal contexts={}\nlocal refresh=function() end\nlocal validPreset=function() return false end\nlocal PRIORITIES={OwnedInterior=10,Dealership=20}\nfunction Client.isContinuous() return continuous end\nfunction Client.setContext(owner,preset)\n    assert(PRIORITIES[owner],\"Unknown lighting context\")\n    if not continuous then return false end\n    if not validPreset(preset) then warn(\"[LightingClient] Rejected context preset: \"..tostring(preset)); return false end\n    if contexts[owner]~=preset then contexts[owner]=preset; refresh() end\n    return true\nend\nfunction Client.releaseContext(owner)\n    if contexts[owner] then contexts[owner]=nil; refresh() end\nend\nfunction Client.start()\n    if started then return end\n    started=true\n    local RS=game:GetService(\"ReplicatedStorage\")\n    local Lighting=game:GetService(\"Lighting\")\n    local RunService=game:GetService(\"RunService\")\n    local HttpService=game:GetService(\"HttpService\")\n    local player=game:GetService(\"Players\").LocalPlayer\n    local world=RS:WaitForChild(\"Modules\").Game.World\n    local config=RS:WaitForChild(\"Config\").World.Lighting\n    local tools=RS.Config.Development.ClientTools\n    local deadline=os.clock()+15\n    while Lighting:GetAttribute(\"LightingCycleMode\")==nil and os.clock()<deadline do task.wait(.05) end\n    local mode=Lighting:GetAttribute(\"LightingCycleMode\")\n    assert(mode==\"Stepped\" or mode==\"Continuous\",\"LightingServer did not publish a valid mode before startup timeout\")\n    continuous=mode==\"Continuous\"\n    if not continuous then return end\n    local Cycle=require(world.LightingCycle)\n    local presets=require(world.LightingPresets)\n    local schedule=require(world.LightingSchedule)\n    local skies=RS.Assets.World.Skies\n    local runtime=player:WaitForChild(\"PlayerScripts\"):WaitForChild(\"Runtime\"):WaitForChild(\"World\")\n    local effects={}\n    local specs={Atmosphere=\"Atmosphere\",Bloom=\"BloomEffect\",ColorCorrection=\"ColorCorrectionEffect\",DepthOfField=\"DepthOfFieldEffect\",SunRays=\"SunRaysEffect\"}\n    for name,class in pairs(specs) do\n        local effect=Lighting:FindFirstChild(name)\n        assert(not effect or effect.ClassName==class,\"Unexpected lighting effect class: \"..name)\n        if not effect then effect=Instance.new(class); effect.Name=name; effect.Parent=Lighting end\n        effects[name]=effect\n    end\n    local activeSky=Lighting:FindFirstChild(\"ActiveSky\")\n    if activeSky then assert(activeSky:IsA(\"Sky\"),\"Invalid ActiveSky\") end\n    if not activeSky then activeSky=Instance.new(\"Sky\"); activeSky.Name=\"ActiveSky\"; activeSky.Parent=Lighting end\n    local skyKeys={\"SkyboxBk\",\"SkyboxDn\",\"SkyboxFt\",\"SkyboxLf\",\"SkyboxRt\",\"SkyboxUp\",\"SkyboxOrientation\",\"SunTextureId\",\"MoonTextureId\",\"SunAngularSize\",\"MoonAngularSize\",\"StarCount\",\"CelestialBodiesShown\"}\n    local skyName\n    local function properties(instance,values)\n        for k,v in pairs(values) do if instance[k]~=v then instance[k]=v end end\n    end\n    local function apply(target)\n        properties(Lighting,target.Lighting)\n        for name,effect in pairs(effects) do properties(effect,target[name]) end\n        if skyName~=target.SkyName then\n            local template=skies:FindFirstChild(target.SkyName)\n            assert(template and template:IsA(\"Sky\"),\"Missing sky: \"..tostring(target.SkyName))\n            for _,key in ipairs(skyKeys) do if activeSky[key]~=template[key] then activeSky[key]=template[key] end end\n            skyName=target.SkyName\n        end\n    end\n    local state,cycle\n    local legacyLatitude=config:GetAttribute(\"SteppedGeographicLatitude\") or 189\n    local classic={}\n    for name in pairs(presets) do classic[name]=Cycle.preset(presets,name,legacyLatitude) end\n    validPreset=function(name) return classic[name]~=nil end\n    local connections={}\n    local alive=true\n    local function mark(name,value) if runtime:GetAttribute(name)~=value then runtime:SetAttribute(name,value) end end\n    local function readState()\n        local raw=Lighting:GetAttribute(\"LightingCycleState\")\n        if type(raw)~=\"string\" then return end\n        local incoming=HttpService:JSONDecode(raw)\n        assert(incoming.Version==3 and Cycle.finite(incoming.Epoch),\"Invalid lighting state\")\n        local built=Cycle.build(presets,schedule,incoming)\n        assert(Cycle.finite(incoming.Sunrise) and Cycle.finite(incoming.Sunset) and incoming.Sunrise>=0 and incoming.Sunrise<incoming.Sunset and incoming.Sunset<24,\"Invalid sunrise/sunset\")\n        assert(type(incoming.Auto)==\"boolean\" and Cycle.finite(incoming.ManualClockTime) and incoming.ManualClockTime>=0 and incoming.ManualClockTime<24,\"Invalid manual state\")\n        state,cycle=incoming,built\n        skyName=nil\n    end\n    local lastFailure\n    local function guarded(fn)\n        local ok,err=xpcall(fn,debug.traceback)\n        if not ok then\n            mark(\"LightingRenderError\",tostring(err))\n            if lastFailure~=tostring(err) then warn(\"[LightingClient] \"..tostring(err)); lastFailure=tostring(err) end\n        else lastFailure=nil; mark(\"LightingRenderError\",nil) end\n    end\n    local wasPreview=false\n    local function render()\n        if not alive or not state then return end\n        local seconds=state.Auto and (workspace:GetServerTimeNow()-state.Epoch) or state.ManualClockTime/24*cycle.total\n        local preview=RunService:IsStudio() and tools:GetAttribute(\"LightingPreviewEnabled\")==true and runtime:GetAttribute(\"LightingPreviewClockTime\")\n        local target,info=Cycle.sample(cycle,Cycle.finite(preview) and preview/24*cycle.total or seconds)\n        local owner=\"City\"\n        if Cycle.finite(preview) then owner=\"StudioPreview\"\n        else\n            local priority=0\n            for name,preset in pairs(contexts) do\n                if PRIORITIES[name]>priority then\n                    assert(classic[preset],\"Unknown context preset: \"..tostring(preset))\n                    target=classic[preset]; owner=name; priority=PRIORITIES[name]\n                end\n            end\n        end\n        apply(target)\n        -- Debug scrubbing only; normal city switch signals remain server-owned.\n        if owner==\"StudioPreview\" or wasPreview then\n            local night=Cycle.isNight(info.clock,state.Sunrise,state.Sunset)\n            Lighting:SetAttribute(\"StreetLightsOn\",night); Lighting:SetAttribute(\"WindowMode\",night and \"Night\" or \"Day\")\n        end\n        wasPreview=owner==\"StudioPreview\"\n        mark(\"LightingContext\",owner)\n        mark(\"LightingCycleReady\",true)\n    end\n    refresh=function() guarded(render) end\n    guarded(readState)\n    connections[#connections+1]=Lighting:GetAttributeChangedSignal(\"LightingCycleState\"):Connect(function() guarded(readState); refresh() end)\n    -- Resolve existing interior/preview intent before the first city application.\n    local interior=RS.Config.Garage.Interior\n    if player:GetAttribute(\"OwnedGarageInside\")==true and interior:GetAttribute(\"InteriorEnvironmentLightingEnabled\")~=false then\n        contexts.OwnedInterior=interior:GetAttribute(\"InteriorEnvironmentPreset\") or \"ClearNight\"\n    end\n    if player:GetAttribute(\"GarageSessionActive\")==true and RS.Config.UI.GarageReplacement:GetAttribute(\"PreviewLightingEnabled\")~=false then\n        contexts.Dealership=RS.Config.UI.GarageReplacement:GetAttribute(\"PreviewLightingPreset\") or \"EightPM\"\n    end\n    refresh()\n    -- Keep the single writer aligned with rendering. Resetting a 30 Hz accumulator\n    -- to zero dropped its remainder, producing uneven 2/3-frame atmosphere steps.\n    connections[#connections+1]=RunService.PreRender:Connect(function()\n        refresh()\n    end)\n    connections[#connections+1]=script.Destroying:Connect(function()\n        alive=false\n        for _,connection in ipairs(connections) do connection:Disconnect() end\n        table.clear(connections); table.clear(contexts); refresh=function() end\n    end)\nend\nreturn Client\n",["after"]="-- Sole environment property writer in Continuous mode. Context decisions stay with their owners.\nlocal Client={}\nlocal started=false\nlocal continuous=false\nlocal contexts={}\nlocal refresh=function() end\nlocal validPreset=function() return false end\nlocal PRIORITIES={OwnedInterior=10,Dealership=20}\nfunction Client.isContinuous() return continuous end\nfunction Client.setContext(owner,preset)\n    assert(PRIORITIES[owner],\"Unknown lighting context\")\n    if not continuous then return false end\n    if not validPreset(preset) then warn(\"[LightingClient] Rejected context preset: \"..tostring(preset)); return false end\n    if contexts[owner]~=preset then contexts[owner]=preset; refresh() end\n    return true\nend\nfunction Client.releaseContext(owner)\n    if contexts[owner] then contexts[owner]=nil; refresh() end\nend\nfunction Client.start()\n    if started then return end\n    started=true\n    local RS=game:GetService(\"ReplicatedStorage\")\n    local Lighting=game:GetService(\"Lighting\")\n    local RunService=game:GetService(\"RunService\")\n    local HttpService=game:GetService(\"HttpService\")\n    local player=game:GetService(\"Players\").LocalPlayer\n    local world=RS:WaitForChild(\"Modules\").Game.World\n    local config=RS:WaitForChild(\"Config\").World.Lighting\n    local tools=RS.Config.Development.ClientTools\n    local deadline=os.clock()+15\n    while Lighting:GetAttribute(\"LightingCycleMode\")==nil and os.clock()<deadline do task.wait(.05) end\n    local mode=Lighting:GetAttribute(\"LightingCycleMode\")\n    assert(mode==\"Stepped\" or mode==\"Continuous\",\"LightingServer did not publish a valid mode before startup timeout\")\n    continuous=mode==\"Continuous\"\n    if not continuous then return end\n    local Cycle=require(world.LightingCycle)\n    local presets=require(world.LightingPresets)\n    local schedule=require(world.LightingSchedule)\n    local skies=RS.Assets.World.Skies\n    local runtime=player:WaitForChild(\"PlayerScripts\"):WaitForChild(\"Runtime\"):WaitForChild(\"World\")\n    local effects={}\n    local specs={Atmosphere=\"Atmosphere\",Bloom=\"BloomEffect\",ColorCorrection=\"ColorCorrectionEffect\",DepthOfField=\"DepthOfFieldEffect\",SunRays=\"SunRaysEffect\"}\n    for name,class in pairs(specs) do\n        local effect=Lighting:FindFirstChild(name)\n        assert(not effect or effect.ClassName==class,\"Unexpected lighting effect class: \"..name)\n        if not effect then effect=Instance.new(class); effect.Name=name; effect.Parent=Lighting end\n        effects[name]=effect\n    end\n    -- Client-local dynamic clouds; a look's Clouds section drives them (Cover 0 = none).\n    local clouds=workspace.Terrain:FindFirstChildOfClass(\"Clouds\")\n    if not clouds then clouds=Instance.new(\"Clouds\"); clouds.Name=\"Clouds\"; clouds.Cover=0; clouds.Parent=workspace.Terrain end\n    local activeSky=Lighting:FindFirstChild(\"ActiveSky\")\n    if activeSky then assert(activeSky:IsA(\"Sky\"),\"Invalid ActiveSky\") end\n    if not activeSky then activeSky=Instance.new(\"Sky\"); activeSky.Name=\"ActiveSky\"; activeSky.Parent=Lighting end\n    local skyKeys={\"SkyboxBk\",\"SkyboxDn\",\"SkyboxFt\",\"SkyboxLf\",\"SkyboxRt\",\"SkyboxUp\",\"SkyboxOrientation\",\"SunTextureId\",\"MoonTextureId\",\"SunAngularSize\",\"MoonAngularSize\",\"StarCount\",\"CelestialBodiesShown\"}\n    local skyName\n    local function properties(instance,values)\n        for k,v in pairs(values) do if instance[k]~=v then instance[k]=v end end\n    end\n    local function apply(target)\n        properties(Lighting,target.Lighting)\n        for name,effect in pairs(effects) do properties(effect,target[name]) end\n        if skyName~=target.SkyName then\n            local template=skies:FindFirstChild(target.SkyName)\n            assert(template and template:IsA(\"Sky\"),\"Missing sky: \"..tostring(target.SkyName))\n            for _,key in ipairs(skyKeys) do if activeSky[key]~=template[key] then activeSky[key]=template[key] end end\n            skyName=target.SkyName\n        end\n        if target.Clouds then properties(clouds,target.Clouds) end\n        if target.SkyYaw then\n            local orientation=Vector3.new(0,math.round(target.SkyYaw*10)/10,0)\n            if activeSky.SkyboxOrientation~=orientation then activeSky.SkyboxOrientation=orientation end\n        end\n    end\n    -- The sky art changes at dusk and dawn; load every template up front so the change never shows a blank sky.\n    task.spawn(function() pcall(function() game:GetService(\"ContentProvider\"):PreloadAsync(skies:GetChildren()) end) end)\n    local state,cycle\n    local legacyLatitude=config:GetAttribute(\"SteppedGeographicLatitude\") or 189\n    local classic={}\n    for name in pairs(presets) do classic[name]=Cycle.preset(presets,name,legacyLatitude) end\n    validPreset=function(name) return classic[name]~=nil end\n    local connections={}\n    local alive=true\n    local function mark(name,value) if runtime:GetAttribute(name)~=value then runtime:SetAttribute(name,value) end end\n    local function readState()\n        local raw=Lighting:GetAttribute(\"LightingCycleState\")\n        if type(raw)~=\"string\" then return end\n        local incoming=HttpService:JSONDecode(raw)\n        assert(incoming.Version==3 and Cycle.finite(incoming.Epoch),\"Invalid lighting state\")\n        local built=Cycle.build(presets,schedule,incoming)\n        assert(Cycle.finite(incoming.Sunrise) and Cycle.finite(incoming.Sunset) and incoming.Sunrise>=0 and incoming.Sunrise<incoming.Sunset and incoming.Sunset<24,\"Invalid sunrise/sunset\")\n        assert(type(incoming.Auto)==\"boolean\" and Cycle.finite(incoming.ManualClockTime) and incoming.ManualClockTime>=0 and incoming.ManualClockTime<24,\"Invalid manual state\")\n        state,cycle=incoming,built\n        skyName=nil\n    end\n    local lastFailure\n    local function guarded(fn)\n        local ok,err=xpcall(fn,debug.traceback)\n        if not ok then\n            mark(\"LightingRenderError\",tostring(err))\n            if lastFailure~=tostring(err) then warn(\"[LightingClient] \"..tostring(err)); lastFailure=tostring(err) end\n        else lastFailure=nil; mark(\"LightingRenderError\",nil) end\n    end\n    local wasPreview=false\n    local function render()\n        if not alive or not state then return end\n        local seconds=state.Auto and (workspace:GetServerTimeNow()-state.Epoch) or state.ManualClockTime/24*cycle.total\n        local preview=RunService:IsStudio() and tools:GetAttribute(\"LightingPreviewEnabled\")==true and runtime:GetAttribute(\"LightingPreviewClockTime\")\n        local target,info=Cycle.sample(cycle,Cycle.finite(preview) and preview/24*cycle.total or seconds)\n        local owner=\"City\"\n        if Cycle.finite(preview) then owner=\"StudioPreview\"\n        else\n            local priority=0\n            for name,preset in pairs(contexts) do\n                if PRIORITIES[name]>priority then\n                    assert(classic[preset],\"Unknown context preset: \"..tostring(preset))\n                    target=classic[preset]; owner=name; priority=PRIORITIES[name]\n                end\n            end\n        end\n        apply(target)\n        -- Debug scrubbing only; normal city switch signals remain server-owned.\n        if owner==\"StudioPreview\" or wasPreview then\n            local night=Cycle.isNight(info.clock,state.Sunrise,state.Sunset)\n            Lighting:SetAttribute(\"StreetLightsOn\",night); Lighting:SetAttribute(\"WindowMode\",night and \"Night\" or \"Day\")\n        end\n        wasPreview=owner==\"StudioPreview\"\n        mark(\"LightingContext\",owner)\n        mark(\"LightingCycleReady\",true)\n    end\n    refresh=function() guarded(render) end\n    guarded(readState)\n    connections[#connections+1]=Lighting:GetAttributeChangedSignal(\"LightingCycleState\"):Connect(function() guarded(readState); refresh() end)\n    -- Resolve existing interior/preview intent before the first city application.\n    local interior=RS.Config.Garage.Interior\n    if player:GetAttribute(\"OwnedGarageInside\")==true and interior:GetAttribute(\"InteriorEnvironmentLightingEnabled\")~=false then\n        contexts.OwnedInterior=interior:GetAttribute(\"InteriorEnvironmentPreset\") or \"ClearNight\"\n    end\n    if player:GetAttribute(\"GarageSessionActive\")==true and RS.Config.UI.GarageReplacement:GetAttribute(\"PreviewLightingEnabled\")~=false then\n        contexts.Dealership=RS.Config.UI.GarageReplacement:GetAttribute(\"PreviewLightingPreset\") or \"EightPM\"\n    end\n    refresh()\n    -- Keep the single writer aligned with rendering. Resetting a 30 Hz accumulator\n    -- to zero dropped its remainder, producing uneven 2/3-frame atmosphere steps.\n    connections[#connections+1]=RunService.PreRender:Connect(function()\n        refresh()\n    end)\n    connections[#connections+1]=script.Destroying:Connect(function()\n        alive=false\n        for _,connection in ipairs(connections) do connection:Disconnect() end\n        table.clear(connections); table.clear(contexts); refresh=function() end\n    end)\nend\nreturn Client\n"},{["kind"]="source",["path"]={"ReplicatedStorage","Modules","Game","World","LightingCycle"},["class_name"]="ModuleScript",["before"]="-- Pure solar motion and authored-look evaluation. No services, tasks or instances.\nlocal Cycle={}\nlocal DEFAULTS={\n    Atmosphere={Color=Color3.fromRGB(199,199,199),Decay=Color3.fromRGB(106,112,125),Density=.22,Glare=0,Haze=0,Offset=.2},\n    Bloom={Enabled=true,Intensity=.65,Size=10,Threshold=1.904},\n    ColorCorrection={Enabled=true,Brightness=.05,Contrast=0,Saturation=.4,TintColor=Color3.new(1,1,1)},\n    DepthOfField={Enabled=false,FarIntensity=.084,FocusDistance=.05,InFocusRadius=10,NearIntensity=.75},\n    SunRays={Enabled=false,Intensity=.05,Spread=.713},\n}\nfunction Cycle.finite(v) return type(v)==\"number\" and v==v and math.abs(v)<math.huge end\nlocal function copy(v)\n    if type(v)~=\"table\" then return v end\n    local out={}; for k,x in pairs(v) do out[k]=copy(x) end; return out\nend\nlocal function overlay(a,b)\n    for k,v in pairs(b) do\n        if type(v)==\"table\" then a[k]=a[k] or {}; overlay(a[k],v) else a[k]=v end\n    end\n    return a\nend\nfunction Cycle.preset(presets,name,latitude)\n    assert(type(presets[name])==\"table\",\"Unknown lighting preset: \"..tostring(name))\n    local target=overlay(copy(DEFAULTS),presets[name])\n    target.Lighting.GeographicLatitude=latitude\n    return target\nend\nlocal function compatible(a,b,path)\n    for k,av in pairs(a) do\n        local bv=b[k]; local key=path..\".\"..k\n        assert(typeof(av)==typeof(bv),\"Incompatible look property \"..key)\n        if type(av)==\"table\" then compatible(av,bv,key)\n        elseif type(av)==\"number\" then assert(Cycle.finite(av) and Cycle.finite(bv),\"Nonfinite \"..key)\n        elseif typeof(av)==\"Color3\" then\n            for _,v in ipairs({av.R,av.G,av.B,bv.R,bv.G,bv.B}) do assert(Cycle.finite(v) and v>=0 and v<=1,\"Invalid colour \"..key) end\n        else assert(av==bv,\"Discrete property must be common across looks: \"..key) end\n    end\n    for k in pairs(b) do assert(a[k]~=nil,\"Incomplete look property \"..path..\".\"..k) end\nend\nCycle.fadeGroups={\"Light\",\"Colour\",\"Haze\",\"Glare\",\"Distance\",\"Post\"}\nlocal function smooth(u) u=math.clamp(u,0,1); return u*u*(3-2*u) end\nlocal function groupFor(section,key,value)\n    if section==\"Atmosphere\" then\n        if key==\"Haze\" or key==\"Glare\" then return key end\n        if key==\"Density\" or key==\"Offset\" then return \"Distance\" end\n    end\n    if typeof(value)==\"Color3\" then return \"Colour\" end\n    if section==\"Lighting\" then return \"Light\" end\n    return \"Post\"\nend\nlocal function blend(a,b,weights,section)\n    local out={}\n    for k,av in pairs(a) do\n        local bv=b[k]\n        if type(av)==\"table\" then out[k]=blend(av,bv,weights,k)\n        else\n            local t=weights[groupFor(section,k,av)]\n            if typeof(av)==\"Color3\" then out[k]=av:Lerp(bv,t)\n            elseif type(av)==\"number\" then out[k]=av+(bv-av)*t\n            else out[k]=av end\n        end\n    end\n    return out\nend\nfunction Cycle.build(presets,schedule,settings)\n    assert(Cycle.finite(settings.DurationSeconds) and settings.DurationSeconds>=24 and settings.DurationSeconds<=86400,\"ContinuousCycleDurationSeconds must be 24..86400\")\n    assert(Cycle.finite(settings.Latitude) and settings.Latitude>=-90 and settings.Latitude<=90,\"Invalid continuous latitude\")\n    assert(Cycle.finite(settings.Sunrise) and Cycle.finite(settings.Sunset) and settings.Sunrise>=0 and settings.Sunrise<settings.Sunset and settings.Sunset<24,\"Invalid sunrise/sunset\")\n    assert(type(settings.SkyName)==\"string\" and settings.SkyName~=\"\",\"Missing ContinuousSkyName\")\n    assert(type(settings.Points)==\"table\" and #settings.Points>=2 and #settings.Points<=32,\"Use 2..32 look milestones\")\n    assert(Cycle.finite(settings.RayFadeHours) and settings.RayFadeHours>0 and settings.RayFadeHours<=(24-settings.Sunset+settings.Sunrise)/2,\"ContinuousRayFadeHours must be positive and fit the night interval\")\n    local cycle={total=settings.DurationSeconds,points={},byName={},indices={},sunrise=settings.Sunrise,sunset=settings.Sunset,rayFadeHours=settings.RayFadeHours}\n    for i,stage in ipairs(schedule) do cycle.indices[stage.Preset]=i end\n    local anchors={Midnight=0,Sunrise=settings.Sunrise,Sunset=settings.Sunset}\n    local names={}\n    for _,row in ipairs(settings.Points) do\n        assert(type(row.Name)==\"string\" and not names[row.Name],\"Duplicate milestone name\"); names[row.Name]=true\n        local anchor=anchors[row.Anchor]; assert(anchor~=nil,\"Anchor must be Midnight, Sunrise or Sunset\")\n        assert(Cycle.finite(row.OffsetHours) and math.abs(row.OffsetHours)<=24,\"Invalid OffsetHours\")\n        assert(Cycle.finite(row.HoldHours) and row.HoldHours>=0 and row.HoldHours<24,\"Invalid HoldHours\")\n        assert(cycle.indices[row.Preset],\"Preset must retain an existing schedule identity\")\n        local target=Cycle.preset(presets,row.Preset,settings.Latitude)\n        local authored=settings.Presets and settings.Presets[row.Preset]\n        assert(type(authored)==\"table\",\"Missing editable continuous preset: \"..row.Preset)\n        for section,properties in pairs(authored) do\n            assert(type(target[section])==\"table\" and type(properties)==\"table\",\"Unknown preset section: \"..tostring(section))\n            for key,value in pairs(properties) do\n                assert(key~=\"ClockTime\" and key~=\"TimeOfDay\" and key~=\"GeographicLatitude\",\"Solar properties belong to cycle settings\")\n                local expected=target[section][key]\n                assert(expected~=nil,\"Unknown lighting property: \"..section..\".\"..key)\n                if typeof(expected)==\"Color3\" then\n                    assert(type(value)==\"table\" and value.Type==\"Color3\",\"Expected Color3 attribute: \"..key)\n                    for _,component in ipairs({value.R,value.G,value.B}) do assert(Cycle.finite(component) and component>=0 and component<=1,\"Invalid colour: \"..key) end\n                    assert(value.R~=nil and value.G~=nil and value.B~=nil,\"Incomplete colour\")\n                    value=Color3.new(value.R,value.G,value.B)\n                end\n                assert(typeof(value)==typeof(expected),\"Wrong attribute type: \"..section..\".\"..key)\n                target[section][key]=value\n            end\n        end\n        target.Lighting.ClockTime=0; target.SkyName=settings.SkyName\n        assert(target.SunRays.Intensity>=0 and target.SunRays.Intensity<=1 and target.SunRays.Spread>=0 and target.SunRays.Spread<=1,\"SunRays intensity/spread must be 0..1\")\n        local fades={}\n        for _,group in ipairs(Cycle.fadeGroups) do\n            local first,last=row[group..\"FadeStart\"],row[group..\"FadeEnd\"]\n            assert(Cycle.finite(first) and Cycle.finite(last) and first>=0 and first<last and last<=1,\"Invalid \"..group..\"FadeStart/End on \"..row.Name..\": require 0 <= start < end <= 1\")\n            fades[group]={first,last}\n        end\n        local point={name=row.Name,preset=row.Preset,hour=(anchor+row.OffsetHours)%24,halfHold=row.HoldHours/2,target=target,fades=fades}\n        cycle.points[#cycle.points+1]=point\n        cycle.byName[row.Preset]=cycle.byName[row.Preset] or {}; table.insert(cycle.byName[row.Preset],point)\n    end\n    table.sort(cycle.points,function(a,b) return a.hour<b.hour end)\n    for i,a in ipairs(cycle.points) do\n        local b=cycle.points[i%#cycle.points+1]\n        a.distance=(b.hour-a.hour)%24\n        assert(a.distance>0 and a.halfHold+b.halfHold<a.distance,\"Duplicate or overlapping milestone holds: \"..a.name..\" / \"..b.name)\n        compatible(a.target,b.target,\"Look\")\n    end\n    return cycle\nend\nfunction Cycle.sample(cycle,seconds)\n    assert(Cycle.finite(seconds),\"Invalid cycle position\")\n    local clock=(seconds%cycle.total)/cycle.total*24\n    local index=#cycle.points\n    for i,a in ipairs(cycle.points) do if a.hour<=clock then index=i else break end end\n    local a=cycle.points[index]; local b=cycle.points[index%#cycle.points+1]\n    local elapsed=(clock-a.hour)%24\n    local u=math.clamp((elapsed-a.halfHold)/(a.distance-a.halfHold-b.halfHold),0,1)\n    local weight=smooth(u)\n    local weights={}\n    for group,range in pairs(a.fades) do weights[group]=smooth((u-range[1])/(range[2]-range[1])) end\n    local target=blend(a.target,b.target,weights)\n    target.Lighting.ClockTime=clock\n    -- Preserve full rays through both horizons, then fade in the adjacent twilight.\n    -- Apply only to outdoor samples; original interior/context targets bypass this gate.\n    local solar=(clock-cycle.sunrise)%24\n    local daylight=cycle.sunset-cycle.sunrise\n    local rayWeight=1\n    if solar>daylight then\n        rayWeight=math.max(1-smooth((solar-daylight)/cycle.rayFadeHours),1-smooth((24-solar)/cycle.rayFadeHours))\n    end\n    target.SunRays.Intensity*=rayWeight\n    local preset=weight<.5 and a.preset or b.preset\n    return target,{clock=clock,preset=preset,index=cycle.indices[preset],from=a.preset,to=b.preset,weight=weight,weights=weights,rayWeight=rayWeight,endsIn=(a.distance-elapsed)*cycle.total/24}\nend\nfunction Cycle.previewClock(cycle,preset)\n    local points=cycle.byName[preset]; assert(points,\"Preset is not in the continuous timeline\")\n    if #points==2 then\n        local a,b=points[1].hour,points[2].hour\n        local clock=(a+((b-a+12)%24-12)/2)%24\n        local _,info=Cycle.sample(cycle,clock/24*cycle.total)\n        if info.from==preset and info.to==preset then return clock end\n    end\n    return points[1].hour\nend\nfunction Cycle.isNight(clock,sunrise,sunset) return clock<sunrise or clock>=sunset end\nreturn Cycle\n",["after"]="-- Pure solar motion and authored-look evaluation. No services, tasks or instances.\nlocal Cycle={}\nlocal DEFAULTS={\n    Atmosphere={Color=Color3.fromRGB(199,199,199),Decay=Color3.fromRGB(106,112,125),Density=.22,Glare=0,Haze=0,Offset=.2},\n    Bloom={Enabled=true,Intensity=.65,Size=10,Threshold=1.904},\n    ColorCorrection={Enabled=true,Brightness=.05,Contrast=0,Saturation=.4,TintColor=Color3.new(1,1,1)},\n    DepthOfField={Enabled=false,FarIntensity=.084,FocusDistance=.05,InFocusRadius=10,NearIntensity=.75},\n    SunRays={Enabled=false,Intensity=.05,Spread=.713},\n    -- Cover 0 draws nothing, so looks without a Clouds section are unchanged.\n    Clouds={Enabled=true,Cover=0,Density=.3,Color=Color3.new(1,1,1)},\n}\nlocal BLACK=Color3.new(0,0,0)\nlocal VEIL_HAZE=5\nfunction Cycle.finite(v) return type(v)==\"number\" and v==v and math.abs(v)<math.huge end\nlocal function copy(v)\n    if type(v)~=\"table\" then return v end\n    local out={}; for k,x in pairs(v) do out[k]=copy(x) end; return out\nend\nlocal function overlay(a,b)\n    for k,v in pairs(b) do\n        if type(v)==\"table\" then a[k]=a[k] or {}; overlay(a[k],v) else a[k]=v end\n    end\n    return a\nend\nfunction Cycle.preset(presets,name,latitude)\n    assert(type(presets[name])==\"table\",\"Unknown lighting preset: \"..tostring(name))\n    local target=overlay(copy(DEFAULTS),presets[name])\n    target.Lighting.GeographicLatitude=latitude\n    return target\nend\nlocal function compatible(a,b,path)\n    for k,av in pairs(a) do\n        local bv=b[k]; local key=path..\".\"..k\n        assert(typeof(av)==typeof(bv),\"Incompatible look property \"..key)\n        if type(av)==\"table\" then compatible(av,bv,key)\n        elseif type(av)==\"number\" then assert(Cycle.finite(av) and Cycle.finite(bv),\"Nonfinite \"..key)\n        elseif typeof(av)==\"Color3\" then\n            for _,v in ipairs({av.R,av.G,av.B,bv.R,bv.G,bv.B}) do assert(Cycle.finite(v) and v>=0 and v<=1,\"Invalid colour \"..key) end\n        else assert(av==bv,\"Discrete property must be common across looks: \"..key) end\n    end\n    for k in pairs(b) do assert(a[k]~=nil,\"Incomplete look property \"..path..\".\"..k) end\nend\nCycle.fadeGroups={\"Light\",\"Colour\",\"Haze\",\"Glare\",\"Distance\",\"Post\"}\nlocal function smooth(u) u=math.clamp(u,0,1); return u*u*(3-2*u) end\n-- Roblox: sun direction = (-sin H cos phi, cos H cos phi, sin phi), H=(ClockTime-12)*15 deg, phi=latitude-23.5 deg.\n-- Returns the SkyboxOrientation yaw that puts art baked at azimuth 0 (-Z) under the sun.\nlocal function sunYaw(clock,latitude)\n    local H=math.rad((clock-12)*15); local phi=math.rad(latitude-23.5)\n    return math.deg(math.atan2(math.sin(H)*math.cos(phi),-math.sin(phi)))\nend\nlocal function clockDistance(a,b) local d=math.abs(a-b)%24; return math.min(d,24-d) end\nlocal function groupFor(section,key,value)\n    if section==\"Atmosphere\" then\n        if key==\"Haze\" or key==\"Glare\" then return key end\n        if key==\"Density\" or key==\"Offset\" then return \"Distance\" end\n    end\n    if typeof(value)==\"Color3\" then return \"Colour\" end\n    if section==\"Lighting\" then return \"Light\" end\n    return \"Post\"\nend\nlocal function blend(a,b,weights,section)\n    local out={}\n    for k,av in pairs(a) do\n        local bv=b[k]\n        if type(av)==\"table\" then out[k]=blend(av,bv,weights,k)\n        else\n            local t=weights[groupFor(section,k,av)]\n            if typeof(av)==\"Color3\" then out[k]=av:Lerp(bv,t)\n            elseif type(av)==\"number\" then out[k]=av+(bv-av)*t\n            else out[k]=av end\n        end\n    end\n    return out\nend\nfunction Cycle.build(presets,schedule,settings)\n    assert(Cycle.finite(settings.DurationSeconds) and settings.DurationSeconds>=24 and settings.DurationSeconds<=86400,\"ContinuousCycleDurationSeconds must be 24..86400\")\n    assert(Cycle.finite(settings.Latitude) and settings.Latitude>=-90 and settings.Latitude<=90,\"Invalid continuous latitude\")\n    assert(Cycle.finite(settings.Sunrise) and Cycle.finite(settings.Sunset) and settings.Sunrise>=0 and settings.Sunrise<settings.Sunset and settings.Sunset<24,\"Invalid sunrise/sunset\")\n    assert(type(settings.SkyName)==\"string\" and settings.SkyName~=\"\",\"Missing ContinuousSkyName\")\n    assert(type(settings.Points)==\"table\" and #settings.Points>=2 and #settings.Points<=32,\"Use 2..32 look milestones\")\n    assert(Cycle.finite(settings.RayFadeHours) and settings.RayFadeHours>0 and settings.RayFadeHours<=(24-settings.Sunset+settings.Sunrise)/2,\"ContinuousRayFadeHours must be positive and fit the night interval\")\n    local cycle={total=settings.DurationSeconds,points={},byName={},indices={},sunrise=settings.Sunrise,sunset=settings.Sunset,rayFadeHours=settings.RayFadeHours}\n    for i,stage in ipairs(schedule) do cycle.indices[stage.Preset]=i end\n    cycle.latitude=settings.Latitude; cycle.skyName=settings.SkyName\n    cycle.followSun=settings.SkyFollowsSun==true\n    assert(not cycle.followSun or settings.Sunset-settings.Sunrise>2,\"ContinuousSkyFollowsSun needs more than two daylight hours\")\n    if settings.NightSkyName~=nil then\n        local first,last,veil=settings.NightSkyStart,settings.NightSkyEnd,settings.NightSkyVeilHours\n        assert(type(settings.NightSkyName)==\"string\" and settings.NightSkyName~=\"\",\"Invalid ContinuousNightSkyName\")\n        assert(Cycle.finite(first) and Cycle.finite(last) and first>settings.Sunset and first<24 and last>=0 and last<settings.Sunrise,\"Night sky must start after sunset and end before sunrise\")\n        assert(Cycle.finite(veil) and veil>=0 and veil<=math.min(first-settings.Sunset,settings.Sunrise-last),\"NightSkyVeilHours must fit between the horizon and the sky change\")\n        cycle.night={name=settings.NightSkyName,first=first,last=last,veil=veil}\n    end\n    local anchors={Midnight=0,Sunrise=settings.Sunrise,Sunset=settings.Sunset}\n    local names={}\n    for _,row in ipairs(settings.Points) do\n        assert(type(row.Name)==\"string\" and not names[row.Name],\"Duplicate milestone name\"); names[row.Name]=true\n        local anchor=anchors[row.Anchor]; assert(anchor~=nil,\"Anchor must be Midnight, Sunrise or Sunset\")\n        assert(Cycle.finite(row.OffsetHours) and math.abs(row.OffsetHours)<=24,\"Invalid OffsetHours\")\n        assert(Cycle.finite(row.HoldHours) and row.HoldHours>=0 and row.HoldHours<24,\"Invalid HoldHours\")\n        assert(cycle.indices[row.Preset],\"Preset must retain an existing schedule identity\")\n        local target=Cycle.preset(presets,row.Preset,settings.Latitude)\n        local authored=settings.Presets and settings.Presets[row.Preset]\n        assert(type(authored)==\"table\",\"Missing editable continuous preset: \"..row.Preset)\n        for section,properties in pairs(authored) do\n            assert(type(target[section])==\"table\" and type(properties)==\"table\",\"Unknown preset section: \"..tostring(section))\n            for key,value in pairs(properties) do\n                assert(key~=\"ClockTime\" and key~=\"TimeOfDay\" and key~=\"GeographicLatitude\",\"Solar properties belong to cycle settings\")\n                local expected=target[section][key]\n                assert(expected~=nil,\"Unknown lighting property: \"..section..\".\"..key)\n                if typeof(expected)==\"Color3\" then\n                    assert(type(value)==\"table\" and value.Type==\"Color3\",\"Expected Color3 attribute: \"..key)\n                    for _,component in ipairs({value.R,value.G,value.B}) do assert(Cycle.finite(component) and component>=0 and component<=1,\"Invalid colour: \"..key) end\n                    assert(value.R~=nil and value.G~=nil and value.B~=nil,\"Incomplete colour\")\n                    value=Color3.new(value.R,value.G,value.B)\n                end\n                assert(typeof(value)==typeof(expected),\"Wrong attribute type: \"..section..\".\"..key)\n                target[section][key]=value\n            end\n        end\n        target.Lighting.ClockTime=0; target.SkyName=settings.SkyName\n        assert(target.SunRays.Intensity>=0 and target.SunRays.Intensity<=1 and target.SunRays.Spread>=0 and target.SunRays.Spread<=1,\"SunRays intensity/spread must be 0..1\")\n        local fades={}\n        for _,group in ipairs(Cycle.fadeGroups) do\n            local first,last=row[group..\"FadeStart\"],row[group..\"FadeEnd\"]\n            assert(Cycle.finite(first) and Cycle.finite(last) and first>=0 and first<last and last<=1,\"Invalid \"..group..\"FadeStart/End on \"..row.Name..\": require 0 <= start < end <= 1\")\n            fades[group]={first,last}\n        end\n        local point={name=row.Name,preset=row.Preset,hour=(anchor+row.OffsetHours)%24,halfHold=row.HoldHours/2,target=target,fades=fades}\n        cycle.points[#cycle.points+1]=point\n        cycle.byName[row.Preset]=cycle.byName[row.Preset] or {}; table.insert(cycle.byName[row.Preset],point)\n    end\n    table.sort(cycle.points,function(a,b) return a.hour<b.hour end)\n    for i,a in ipairs(cycle.points) do\n        local b=cycle.points[i%#cycle.points+1]\n        a.distance=(b.hour-a.hour)%24\n        assert(a.distance>0 and a.halfHold+b.halfHold<a.distance,\"Duplicate or overlapping milestone holds: \"..a.name..\" / \"..b.name)\n        compatible(a.target,b.target,\"Look\")\n    end\n    return cycle\nend\nfunction Cycle.sample(cycle,seconds)\n    assert(Cycle.finite(seconds),\"Invalid cycle position\")\n    local clock=(seconds%cycle.total)/cycle.total*24\n    local index=#cycle.points\n    for i,a in ipairs(cycle.points) do if a.hour<=clock then index=i else break end end\n    local a=cycle.points[index]; local b=cycle.points[index%#cycle.points+1]\n    local elapsed=(clock-a.hour)%24\n    local u=math.clamp((elapsed-a.halfHold)/(a.distance-a.halfHold-b.halfHold),0,1)\n    local weight=smooth(u)\n    local weights={}\n    for group,range in pairs(a.fades) do weights[group]=smooth((u-range[1])/(range[2]-range[1])) end\n    local target=blend(a.target,b.target,weights)\n    target.Lighting.ClockTime=clock\n    -- Preserve full rays through both horizons, then fade in the adjacent twilight.\n    -- Apply only to outdoor samples; original interior/context targets bypass this gate.\n    local solar=(clock-cycle.sunrise)%24\n    local daylight=cycle.sunset-cycle.sunrise\n    local rayWeight=1\n    if solar>daylight then\n        rayWeight=math.max(1-smooth((solar-daylight)/cycle.rayFadeHours),1-smooth((24-solar)/cycle.rayFadeHours))\n    end\n    target.SunRays.Intensity*=rayWeight\n    -- Night art: Roblox dims any skybox while the sun is down, so the night sky is shown day-for-night. The engine\n    -- clock moves twelve hours, which puts the sun where the moon was (same light direction); the night template\n    -- draws that sun as the moon. info.clock stays the game clock. The art cannot cross-fade, so the change happens\n    -- behind a veil: haze up and black, no key light, sky fill and reflections dipped.\n    local night=cycle.night\n    local nightSky,veil=false,0\n    if night then\n        nightSky=(clock-night.first)%24<(night.last-night.first)%24\n        if nightSky then target.Lighting.ClockTime=(clock+12)%24 end\n        if night.veil>0 then veil=1-smooth(math.min(clockDistance(clock,night.first),clockDistance(clock,night.last))/night.veil) end\n        if veil>0 then\n            local light,air=target.Lighting,target.Atmosphere\n            light.Brightness*=1-veil\n            light.EnvironmentDiffuseScale*=1-.9*veil; light.EnvironmentSpecularScale*=1-.9*veil\n            air.Color=air.Color:Lerp(BLACK,veil); air.Decay=air.Decay:Lerp(BLACK,veil)\n            air.Glare*=1-veil; air.Haze+=math.max(0,VEIL_HAZE-air.Haze)*veil\n            target.Clouds.Color=target.Clouds.Color:Lerp(BLACK,veil)\n        end\n    end\n    target.SkyName=nightSky and night.name or cycle.skyName\n    target.SkyYaw=nil\n    if cycle.followSun and not nightSky then target.SkyYaw=Cycle.skyYaw(cycle,clock) end\n    local preset=weight<.5 and a.preset or b.preset\n    return target,{sky=target.SkyName,veil=veil,clock=clock,preset=preset,index=cycle.indices[preset],from=a.preset,to=b.preset,weight=weight,weights=weights,rayWeight=rayWeight,endsIn=(a.distance-elapsed)*cycle.total/24}\nend\n-- Day art keeps its baked glow at the sunrise side until an hour after sunrise, turns once through the midday\n-- sun's side, and sits at the sunset side from an hour before sunset. Following the sun exactly would spin the\n-- sky at noon, when the sun is nearly overhead.\nfunction Cycle.skyYaw(cycle,clock)\n    local rise,set=sunYaw(cycle.sunrise,cycle.latitude),sunYaw(cycle.sunset,cycle.latitude)\n    local first,last=cycle.sunrise+1,cycle.sunset-1\n    if clock<=first then return rise end\n    if clock>=last then return set end\n    local turn=(set-rise+180)%360-180\n    return rise+turn*smooth((clock-first)/(last-first))\nend\nfunction Cycle.previewClock(cycle,preset)\n    local points=cycle.byName[preset]; assert(points,\"Preset is not in the continuous timeline\")\n    if #points==2 then\n        local a,b=points[1].hour,points[2].hour\n        local clock=(a+((b-a+12)%24-12)/2)%24\n        local _,info=Cycle.sample(cycle,clock/24*cycle.total)\n        if info.from==preset and info.to==preset then return clock end\n    end\n    return points[1].hour\nend\nfunction Cycle.isNight(clock,sunrise,sunset) return clock<sunrise or clock>=sunset end\nreturn Cycle\n"},{["kind"]="source",["path"]={"ReplicatedStorage","Modules","Game","World","LightingCycleDefinition"},["class_name"]="ModuleScript",["before"]="-- Authoring adapter only. Tune Config.World.Lighting and its ContinuousLooks folders.\nlocal Definition={}\nfunction Definition.read(config)\n    local points={}\n    local looks=assert(config:FindFirstChild(\"ContinuousLooks\"),\"Missing ContinuousLooks\")\n    local palette=assert(config:FindFirstChild(\"ContinuousPresets\"),\"Missing ContinuousPresets\")\n    for _,folder in ipairs(looks:GetChildren()) do\n        assert(folder:IsA(\"Folder\"),\"ContinuousLooks accepts Folder milestones only\")\n        local point={Name=folder.Name,Preset=folder:GetAttribute(\"Preset\"),Anchor=folder:GetAttribute(\"Anchor\"),OffsetHours=folder:GetAttribute(\"OffsetHours\"),HoldHours=folder:GetAttribute(\"HoldHours\")}\n        for _,group in ipairs({\"Light\",\"Colour\",\"Haze\",\"Glare\",\"Distance\",\"Post\"}) do\n            point[group..\"FadeStart\"]=folder:GetAttribute(group..\"FadeStart\")\n            point[group..\"FadeEnd\"]=folder:GetAttribute(group..\"FadeEnd\")\n        end\n        points[#points+1]=point\n    end\n    table.sort(points,function(a,b) return a.Name<b.Name end)\n    local presets={}\n    for _,look in ipairs(palette:GetChildren()) do\n        assert(look:IsA(\"Folder\") and not presets[look.Name],\"Invalid or duplicate continuous preset\")\n        local sections={}; presets[look.Name]=sections\n        for _,section in ipairs(look:GetChildren()) do\n            assert(section:IsA(\"Folder\") and not sections[section.Name] and #section:GetChildren()==0,\"Invalid preset section\")\n            local properties={}; sections[section.Name]=properties\n            for key,value in pairs(section:GetAttributes()) do\n                properties[key]=typeof(value)==\"Color3\" and {Type=\"Color3\",R=value.R,G=value.G,B=value.B} or value\n            end\n        end\n    end\n    return {\n        DurationSeconds=config:GetAttribute(\"ContinuousCycleDurationSeconds\"),\n        Latitude=config:GetAttribute(\"ContinuousGeographicLatitude\"),\n        Sunrise=config:GetAttribute(\"SunriseClockTime\"),Sunset=config:GetAttribute(\"SunsetClockTime\"),\n        SkyName=config:GetAttribute(\"ContinuousSkyName\"),Points=points,Presets=presets,\n        RayFadeHours=config:GetAttribute(\"ContinuousRayFadeHours\"),\n        Auto=config:GetAttribute(\"AutoCycleEnabled\")~=false,\n        Synchronized=config:GetAttribute(\"SynchronizeAcrossServers\")~=false,\n        ManualClockTime=config:GetAttribute(\"ContinuousManualClockTime\"),\n    }\nend\nreturn Definition\n",["after"]="-- Authoring adapter only. Tune Config.World.Lighting and its ContinuousLooks folders.\nlocal Definition={}\nfunction Definition.read(config)\n    local points={}\n    local looks=assert(config:FindFirstChild(\"ContinuousLooks\"),\"Missing ContinuousLooks\")\n    local palette=assert(config:FindFirstChild(\"ContinuousPresets\"),\"Missing ContinuousPresets\")\n    for _,folder in ipairs(looks:GetChildren()) do\n        assert(folder:IsA(\"Folder\"),\"ContinuousLooks accepts Folder milestones only\")\n        local point={Name=folder.Name,Preset=folder:GetAttribute(\"Preset\"),Anchor=folder:GetAttribute(\"Anchor\"),OffsetHours=folder:GetAttribute(\"OffsetHours\"),HoldHours=folder:GetAttribute(\"HoldHours\")}\n        for _,group in ipairs({\"Light\",\"Colour\",\"Haze\",\"Glare\",\"Distance\",\"Post\"}) do\n            point[group..\"FadeStart\"]=folder:GetAttribute(group..\"FadeStart\")\n            point[group..\"FadeEnd\"]=folder:GetAttribute(group..\"FadeEnd\")\n        end\n        points[#points+1]=point\n    end\n    table.sort(points,function(a,b) return a.Name<b.Name end)\n    local presets={}\n    for _,look in ipairs(palette:GetChildren()) do\n        assert(look:IsA(\"Folder\") and not presets[look.Name],\"Invalid or duplicate continuous preset\")\n        local sections={}; presets[look.Name]=sections\n        for _,section in ipairs(look:GetChildren()) do\n            assert(section:IsA(\"Folder\") and not sections[section.Name] and #section:GetChildren()==0,\"Invalid preset section\")\n            local properties={}; sections[section.Name]=properties\n            for key,value in pairs(section:GetAttributes()) do\n                properties[key]=typeof(value)==\"Color3\" and {Type=\"Color3\",R=value.R,G=value.G,B=value.B} or value\n            end\n        end\n    end\n    return {\n        DurationSeconds=config:GetAttribute(\"ContinuousCycleDurationSeconds\"),\n        Latitude=config:GetAttribute(\"ContinuousGeographicLatitude\"),\n        Sunrise=config:GetAttribute(\"SunriseClockTime\"),Sunset=config:GetAttribute(\"SunsetClockTime\"),\n        SkyName=config:GetAttribute(\"ContinuousSkyName\"),Points=points,Presets=presets,\n        RayFadeHours=config:GetAttribute(\"ContinuousRayFadeHours\"),\n        Auto=config:GetAttribute(\"AutoCycleEnabled\")~=false,\n        Synchronized=config:GetAttribute(\"SynchronizeAcrossServers\")~=false,\n        ManualClockTime=config:GetAttribute(\"ContinuousManualClockTime\"),\n        -- Optional night sky art (absent: one sky all day, as before).\n        NightSkyName=config:GetAttribute(\"ContinuousNightSkyName\"),\n        NightSkyStart=config:GetAttribute(\"NightSkyStartClockTime\"),NightSkyEnd=config:GetAttribute(\"NightSkyEndClockTime\"),\n        NightSkyVeilHours=config:GetAttribute(\"NightSkyVeilHours\"),\n        SkyFollowsSun=config:GetAttribute(\"ContinuousSkyFollowsSun\")==true,\n    }\nend\nreturn Definition\n"},{["kind"]="source",["path"]={"ServerStorage","Modules","Game","World","LightingServer"},["class_name"]="ModuleScript",["before"]="-- Canonical feature implementation; startup is owned by the composition root.\nlocal Service = {}\nlocal state\nfunction Service.start()\nif state then assert(state==\"ready\", \"Service already starting or failed\"); return end\nstate=\"starting\"\nlocal ok,message=xpcall(function()\n-- NTR Lighting Phase AQ - isolated six-stage server owner\nlocal Lighting = game:GetService(\"Lighting\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal shared = game:GetService(\"ReplicatedStorage\")\nlocal presets = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"World\"):WaitForChild(\"LightingPresets\"))\nlocal skyPresets = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Assets\"):WaitForChild(\"World\"):WaitForChild(\"Skies\")\nlocal config = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Config\"):WaitForChild(\"World\"):WaitForChild(\"Lighting\")\nlocal schedule = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"World\"):WaitForChild(\"LightingSchedule\"))\n\n-- Server state stays authoritative; only the client renderer writes the environment.\nlocal requestedMode=config:GetAttribute(\"CycleMode\") or \"Stepped\"\nassert(requestedMode==\"Stepped\" or requestedMode==\"Continuous\",\"Invalid CycleMode\")\nLighting:SetAttribute(\"LightingCycleMode\",requestedMode)\nif requestedMode==\"Continuous\" then\n    local RunService=game:GetService(\"RunService\")\n    local HttpService=game:GetService(\"HttpService\")\n    local World=ReplicatedStorage.Modules.Game.World\n    local Cycle=require(World.LightingCycle)\n    local Definition=require(World.LightingCycleDefinition)\n    local looks=config:FindFirstChild(\"ContinuousLooks\")\n    assert(looks and looks:IsA(\"Folder\"),\"Missing ContinuousLooks config\")\n    local palette=config:FindFirstChild(\"ContinuousPresets\")\n    assert(palette and palette:IsA(\"Folder\"),\"Missing ContinuousPresets config\")\n    local sessionEpoch=workspace:GetServerTimeNow()\n    local cycle,settings,configError\n    local dirty=true\n    local revision=0\n    local function put(name,value) if Lighting:GetAttribute(name)~=value then Lighting:SetAttribute(name,value) end end\n    local function rebuild()\n        local candidate=Definition.read(config)\n        local built=Cycle.build(presets,schedule,candidate)\n        assert(Cycle.finite(candidate.ManualClockTime) and candidate.ManualClockTime>=0 and candidate.ManualClockTime<24,\"ContinuousManualClockTime must be 0..<24\")\n        local sky=skyPresets:FindFirstChild(candidate.SkyName)\n        assert(sky and sky:IsA(\"Sky\"),\"ContinuousSkyName must name an existing sky template\")\n        revision+=1\n        candidate.Version=3; candidate.Revision=revision\n        candidate.Epoch=candidate.Synchronized and 0 or sessionEpoch\n        local encoded=HttpService:JSONEncode(candidate)\n        cycle,settings=built,candidate\n        put(\"LightingCycleState\",encoded)\n    end\n    -- Reject a bad edit atomically; keep the last valid configuration until repaired.\n    local function update()\n        if dirty then\n            dirty=false\n            local success,problem=xpcall(rebuild,debug.traceback)\n            configError=not success and tostring(problem) or nil\n            put(\"LightingCycleError\",configError)\n            if configError then warn(\"[LightingServer] Rejected lighting config: \"..configError) end\n        end\n        assert(settings,\"No valid lighting configuration\")\n        local now=workspace:GetServerTimeNow()\n        local seconds=settings.Auto and (now-settings.Epoch) or settings.ManualClockTime/24*cycle.total\n        local _,info=Cycle.sample(cycle,seconds)\n        local night=Cycle.isNight(info.clock,settings.Sunrise,settings.Sunset)\n        put(\"LightingPreset\",info.preset); put(\"LightingStageIndex\",info.index)\n        -- Compatibility metadata: next visual milestone, not a separate timer.\n        put(\"LightingStageEndsAtUnix\",settings.Auto and math.floor(now+info.endsIn+.5) or 0)\n        put(\"StreetLightsOn\",night); put(\"WindowMode\",night and \"Night\" or \"Day\")\n        put(\"StreetLightBrightness\",math.max(0,tonumber(config:GetAttribute(\"DefaultStreetLightBrightness\")) or 2))\n    end\n    local connections={}\n    local watched={}\n    local function changed() dirty=true end\n    local function watch(folder)\n        if watched[folder] then return end\n        watched[folder]={folder.AttributeChanged:Connect(changed),folder:GetPropertyChangedSignal(\"Name\"):Connect(changed)}\n        dirty=true\n    end\n    local function unwatch(folder)\n        if watched[folder] then for _,c in ipairs(watched[folder]) do c:Disconnect() end; watched[folder]=nil end\n        dirty=true\n    end\n    for _,root in ipairs({looks,palette}) do\n        for _,folder in ipairs(root:GetDescendants()) do watch(folder) end\n        connections[#connections+1]=root.DescendantAdded:Connect(watch)\n        connections[#connections+1]=root.DescendantRemoving:Connect(unwatch)\n    end\n    connections[#connections+1]=config.AttributeChanged:Connect(function(name) if name~=\"CycleMode\" then changed() end end)\n    update()\n    local elapsed=0\n    local lastError\n    connections[#connections+1]=RunService.Heartbeat:Connect(function(dt)\n        elapsed+=dt; if elapsed<.25 then return end; elapsed=0\n        local success,problem=xpcall(update,debug.traceback)\n        if not success then\n            put(\"LightingCycleError\",tostring(problem))\n            if problem~=lastError then warn(\"[LightingServer] \"..tostring(problem)); lastError=problem end\n        elseif not configError then lastError=nil; put(\"LightingCycleError\",nil) end\n    end)\n    script.Destroying:Once(function()\n        for _,connection in ipairs(connections) do connection:Disconnect() end\n        for folder in pairs(watched) do unwatch(folder) end\n        table.clear(connections)\n    end)\n    return\nend\nLighting.GeographicLatitude=config:GetAttribute(\"SteppedGeographicLatitude\") or Lighting.GeographicLatitude\n\n\nlocal function getOrCreateEffect(className, name)\n\tlocal existing = Lighting:FindFirstChild(name)\n\tif existing and existing.ClassName == className then\n\t\treturn existing\n\tend\n\tif existing then existing:Destroy() end\n\tlocal effect = Instance.new(className)\n\teffect.Name = name\n\teffect.Parent = Lighting\n\treturn effect\nend\n\nlocal effects = {\n\tAtmosphere = getOrCreateEffect(\"Atmosphere\", \"Atmosphere\"),\n\tColorCorrection = getOrCreateEffect(\"ColorCorrectionEffect\", \"ColorCorrection\"),\n\tBloom = getOrCreateEffect(\"BloomEffect\", \"Bloom\"),\n\tSunRays = getOrCreateEffect(\"SunRaysEffect\", \"SunRays\"),\n\tDepthOfField = getOrCreateEffect(\"DepthOfFieldEffect\", \"DepthOfField\"),\n}\n\nlocal function applyProperties(instance, properties)\n\tfor propertyName, value in pairs(properties or {}) do\n\t\tif instance == Lighting and propertyName == \"Fogcolor\" then propertyName = \"FogColor\" end\n\t\tlocal ok, err = pcall(function() instance[propertyName] = value end)\n\t\tif not ok then warn(\"[Lighting AQ] Could not apply\", instance.Name, propertyName, err) end\n\tend\nend\n\nlocal function applySky(name)\n\tif not name then return end\n\tlocal template = skyPresets:FindFirstChild(name)\n\tif not template or not template:IsA(\"Sky\") then\n\t\twarn(\"[Lighting AQ] Missing Sky preset:\", name)\n\t\treturn\n\tend\n\tfor _, child in ipairs(Lighting:GetChildren()) do\n\t\tif child:IsA(\"Sky\") then child:Destroy() end\n\tend\n\tlocal clone = template:Clone()\n\tclone.Name = \"ActiveSky\"\n\tclone.Parent = Lighting\nend\n\nlocal currentPreset\nlocal function applyStage(stage, index, endsAtUnix)\n\tlocal preset = presets[stage.Preset]\n\tif not preset then\n\t\twarn(\"[Lighting AQ] Missing preset:\", stage.Preset)\n\t\treturn\n\tend\n\tif currentPreset ~= stage.Preset then\n\t\tapplyProperties(Lighting, preset.Lighting)\n\t\tfor section, effect in pairs(effects) do applyProperties(effect, preset[section]) end\n\t\tapplySky(preset.SkyName)\n\t\tcurrentPreset = stage.Preset\n\t\tprint(\"[Lighting AQ] Applied stage:\", stage.DisplayName or stage.Preset)\n\tend\n\tLighting:SetAttribute(\"LightingPreset\", stage.Preset)\n\tLighting:SetAttribute(\"StreetLightsOn\", stage.StreetLightsOn == true)\n\tLighting:SetAttribute(\"WindowMode\", stage.WindowMode or \"Day\")\n\tLighting:SetAttribute(\"LightingStageIndex\", index)\n\tLighting:SetAttribute(\"LightingStageEndsAtUnix\", endsAtUnix or 0)\nend\n\nlocal localCycleStartedAt = os.clock()\nlocal function stageFromCycle()\n\tlocal base = math.max(1, tonumber(config:GetAttribute(\"BaseDurationSeconds\")) or 300)\n\tlocal total = 0\n\tfor _, stage in ipairs(schedule) do total += base * math.max(0.01, tonumber(stage.DurationWeight) or 1) end\n\tlocal synchronized = config:GetAttribute(\"SynchronizeAcrossServers\") ~= false\n\tlocal now = synchronized and os.time() or (os.clock() - localCycleStartedAt)\n\tlocal position = now % total\n\tlocal cursor = 0\n\tfor index, stage in ipairs(schedule) do\n\t\tlocal duration = base * math.max(0.01, tonumber(stage.DurationWeight) or 1)\n\t\tif position < cursor + duration then\n\t\t\tlocal remaining = cursor + duration - position\n\t\t\treturn stage, index, synchronized and (os.time() + math.ceil(remaining)) or 0\n\t\tend\n\t\tcursor += duration\n\tend\n\treturn schedule[1], 1, 0\nend\n\nlocal function manualStage()\n\tlocal wanted = tostring(config:GetAttribute(\"ManualStage\") or \"Day\")\n\tfor index, stage in ipairs(schedule) do\n\t\tif stage.Preset == wanted then return stage, index end\n\tend\n\twarn(\"[Lighting AQ] Invalid ManualStage; using Day:\", wanted)\n\treturn schedule[1], 1\nend\n\ntask.spawn(function()\nwhile true do\n\tlocal stage, index, endsAt\n\tif config:GetAttribute(\"AutoCycleEnabled\") == false then\n\t\tstage, index = manualStage()\n\t\tendsAt = 0\n\telse\n\t\tstage, index, endsAt = stageFromCycle()\n\tend\n\tapplyStage(stage, index, endsAt)\n\ttask.wait(1)\nend\nend)\n\nend,debug.traceback)\nstate=ok and \"ready\" or \"failed\"\nassert(ok,message)\nend\nreturn Service\n",["after"]="-- Canonical feature implementation; startup is owned by the composition root.\nlocal Service = {}\nlocal state\nfunction Service.start()\nif state then assert(state==\"ready\", \"Service already starting or failed\"); return end\nstate=\"starting\"\nlocal ok,message=xpcall(function()\n-- NTR Lighting Phase AQ - isolated six-stage server owner\nlocal Lighting = game:GetService(\"Lighting\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal shared = game:GetService(\"ReplicatedStorage\")\nlocal presets = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Modules\"):WaitForChild(\"Game\"):WaitForChild(\"World\"):WaitForChild(\"LightingPresets\"))\nlocal skyPresets = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Assets\"):WaitForChild(\"World\"):WaitForChild(\"Skies\")\nlocal config = game:GetService(\"ReplicatedStorage\"